                             BigDecimal deduction, BigDecimal rate, long rateVersion, String actor,
                             long createdNanos) {
    KeyHolder keys = new GeneratedKeyHolder();
    jdbc.update(con -> {
        PreparedStatement ps = con.prepareStatement(
                "INSERT INTO settlement insert into (settlement_key, batch_key, window_id, channel_id, allocation_key,"
                        + " downstream_user_id, day_start_nanos, occurred_nanos, delivered_volume,"
                        + " loss_volume, upstream_deduction, rate_value, rate_version, status, actor,"
                        + " created_nanos) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'SETTLED', ?, ?)",
                Statement.RETURN_GENERATED_KEYS);
        ps.setString(1, settlementKey);
        ps.setLong(2, batchKey);
        ps.setLong(3, windowId);
        ps.setString(4, channelId);
        ps.setString(5, allocationKey);
        ps.setString(6, downstreamUserId);
        ps.setLong(7, dayStartNanos);
        ps.setLong(8, occurredNanos);
        ps.setBigDecimal(9, delivered);
        ps.setBigDecimal(10, loss);
        ps.setBigDecimal(11, deduction);
        ps.setBigDecimal(12, rate);
        ps.setLong(13, rateVersion);
        ps.setString(14, actor);
        ps.setLong(15, createdNanos);
        return ps;
    }, keys);
    return Objects.requireNonNull(keys.getKey()).longValue();
}

