                                 String allocationKey, String downstreamUserId, String dayUtc,
                                 String occurredUtc, String deliveredVolume, String lossVolume,
                                 String upstreamDeduction, String rate, long rateVersion, String status,
                                 String actor, String createdUtc, String correctionKey) {
}

