/** 单笔核销预校验后的舍入结果。 */
record SettlementMath(BigDecimal delivered, BigDecimal loss, BigDecimal deduction) {
    /** 独立舍入后守恒不成立：上游扣减 != 送达 + 损耗。 */
    boolean conservationBroken() {
        return deduction.compareTo(delivered.add(loss)) != 0;
    }
}

